exercise.referenceSolution:
struct Calibration { int offset; int apply(int raw) const { return raw+offset; } };
class Meter { Calibration calibration_; public: explicit Meter(int offset) : calibration_{offset} {} int read(int raw) const { return calibration_.apply(raw); } };
int solve(int a,int b) { return Meter{b}.read(a); }
